import * as T from './vendor/three.module.js';
import {createCompanion} from './companion.js';
export function createVisitors(scene){
 const peers=new Map(),container=document.querySelector('#visitor-labels'),screen=new T.Vector3();
 function remove(id,p){scene.remove(p.pet.group);p.label.remove();const geometries=new Set(),materials=new Set();p.pet.group.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)materials.add(o.material);});geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());peers.delete(id);}
 window.addEventListener('lab:visitors',e=>{const ids=new Set(e.detail.map(p=>p.id));for(const [id,p]of peers)if(!ids.has(id))remove(id,p);for(const state of e.detail){let peer=peers.get(state.id);if(!peer){const pet=createCompanion({detail:'remote'}),label=document.createElement('span');label.className='visitor-label';label.textContent=state.name;container.append(label);pet.group.position.set(state.x,state.y??.95,state.z);scene.add(pet.group);peer={pet,label,state};peers.set(state.id,peer);}peer.state=state;peer.pet.customize({fur:state.color,accessory:state.accessory});peer.pet.equip(['ski','lift','summit'].includes(state.mode)?(peer.pet.gear==='board'?'board':'ski'):state.mode==='sled'?'sled':peer.pet.gear);}});
 return{update(dt,time,camera){for(const p of peers.values()){const s=p.state,g=p.pet.group,d=Math.hypot(g.position.x-s.x,g.position.z-s.z);g.position.lerp(new T.Vector3(s.x,s.y??.95,s.z),1-Math.exp(-dt*5));const turn=Math.atan2(Math.sin(s.yaw-g.rotation.y),Math.cos(s.yaw-g.rotation.y));g.rotation.y+=turn*(1-Math.exp(-dt*5));p.pet.pose({mode:s.mode,walking:d>.15&&!s.mode,phase:time*7,time,landing:s.gesture==='wave'?.3:0});screen.copy(g.position).add(new T.Vector3(0,1.6,0)).project(camera);p.label.hidden=screen.z>1||screen.z< -1;p.label.style.transform=`translate(${(screen.x*.5+.5)*innerWidth}px,${(-screen.y*.5+.5)*innerHeight}px) translate(-50%,-100%)`;}}};
}
